cases.bad:
// Sending end (popupDictionaryController):
interface PopupCardCreatorPrefill {
  term: string;
  audioUrls?: readonly string[];  // collected
  imageUrls?: readonly string[];   // collected
}

// Receiving end (contentScriptController):
prefill: {
  targetWord: prefill.term,
  // audioUrls + imageUrls NOT mapped — silently dropped
}

// CardCreatorPrefill interface also missing audioUrls/imageUrls
// → TypeScript OK because all fields optional → no error

cases.good:
// Receiving end maps EVERY field:
prefill: {
  targetWord: prefill.term,
  audioUrls: prefill.audioUrls,   // mapped
  imageUrls: prefill.imageUrls,   // mapped
}

// CardCreatorPrefill interface covers all sending-end fields:
interface CardCreatorPrefill {
  targetWord?: string;
  audioUrls?: readonly string[];
  imageUrls?: readonly string[];
}

// Review checklist: diff field-by-field sending interface vs receiving interface.
